assignments.referenceSolution:
This combines three ideas from the lessons: a simple factory keyed by name, a registry populated by a decorator, and entry-point plugins that are discovered cheaply and imported lazily. Treating plugins as untrusted (built-ins win, failures are isolated and chained, duplicates are logged) keeps one bad package from taking the gateway down.

**`provfac.py`**

```python
import logging
import threading
from collections.abc import Callable, Iterable
from typing import Any, Protocol, TypeVar

log = logging.getLogger(__name__)
F = TypeVar("F", bound=Callable[..., Any])


class EntryPointLike(Protocol):
    """The two members of importlib.metadata.EntryPoint that we rely on."""

    name: str

    def load(self) -> Callable[..., Any]: ...


class UnknownProviderError(ValueError):
    """No provider is registered under the requested name."""


class ProviderLoadError(RuntimeError):
    """A discovered plugin could not be imported."""


class ProviderFactory:
    """Simple factory backed by a registry, with lazy plugin entry points."""

    def __init__(self) -> None:
        self._builders: dict[str, Callable[..., Any]] = {}
        self._pending: dict[str, EntryPointLike] = {}
        self._lock = threading.Lock()

    def register(self, name: str) -> Callable[[F], F]:
        def decorator(builder: F) -> F:
            with self._lock:
                if name in self._builders or name in self._pending:
                    raise ValueError(f"provider {name!r} is already registered")
                self._builders[name] = builder
            return builder

        return decorator

    def load_entry_points(self, entry_points: Iterable[EntryPointLike]) -> list[str]:
        """Record plugins without importing them. Built-ins and earlier plugins win."""
        added: list[str] = []
        with self._lock:
            for ep in entry_points:
                if ep.name in self._builders or ep.name in self._pending:
                    log.warning("ignoring plugin %r: name already registered", ep.name)
                    continue
                self._pending[ep.name] = ep
                added.append(ep.name)
        return added

    def names(self) -> list[str]:
        with self._lock:
            return sorted(set(self._builders) | set(self._pending))

    def create(self, name: str, **kwargs: Any) -> Any:
        builder = self._resolve(name)
        return builder(**kwargs)

    def _resolve(self, name: str) -> Callable[..., Any]:
        with self._lock:
            builder = self._builders.get(name)
            if builder is not None:
                return builder
            entry_point = self._pending.get(name)
            if entry_point is None:
                known = sorted(set(self._builders) | set(self._pending))
                raise UnknownProviderError(f"unknown provider {name!r}; known: {known}")
            try:
                builder = entry_point.load()
            except Exception as exc:
                raise ProviderLoadError(f"plugin {name!r} failed to load: {exc}") from exc
            self._builders[name] = builder
            del self._pending[name]
            return builder
```

**`test_provfac.py`**

```python
import logging
import threading

import pytest

from provfac import ProviderFactory, ProviderLoadError, UnknownProviderError


class FakeEntryPoint:
    def __init__(self, name, target=None, error=None):
        self.name = name
        self._target = target
        self._error = error
        self.load_calls = 0

    def load(self):
        self.load_calls += 1
        if self._error:
            raise self._error
        return self._target


class Collect(logging.Handler):
    def __init__(self):
        super().__init__()
        self.messages = []

    def emit(self, record):
        self.messages.append(record.getMessage())


def make_factory():
    factory = ProviderFactory()

    @factory.register("openai")
    def build_openai(model="small"):
        return ("openai", model)

    return factory


def test_create_passes_keyword_arguments() -> None:
    assert make_factory().create("openai", model="big") == ("openai", "big")


def test_unknown_name_lists_known_names() -> None:
    with pytest.raises(UnknownProviderError, match="openai"):
        make_factory().create("mistral")


def test_duplicate_registration_is_rejected() -> None:
    factory = make_factory()
    with pytest.raises(ValueError, match="already registered"):
        factory.register("openai")(lambda: None)


def test_plugins_are_loaded_lazily_and_only_once() -> None:
    factory = make_factory()
    ep = FakeEntryPoint("local", target=lambda: "local-client")
    assert factory.load_entry_points([ep]) == ["local"]
    assert ep.load_calls == 0 and "local" in factory.names()
    assert factory.create("local") == "local-client"
    assert factory.create("local") == "local-client"
    assert ep.load_calls == 1


def test_a_broken_plugin_only_affects_itself() -> None:
    factory = make_factory()
    factory.load_entry_points([FakeEntryPoint("bad", error=ImportError("no module"))])
    with pytest.raises(ProviderLoadError, match="bad"):
        factory.create("bad")
    assert factory.create("openai") == ("openai", "small")


def test_plugin_cannot_replace_a_builtin_and_a_warning_is_logged() -> None:
    factory = make_factory()
    handler = Collect()
    logger = logging.getLogger()  # root: receives records from any module logger
    logger.addHandler(handler)
    try:
        evil = FakeEntryPoint("openai", target=lambda **kw: "hijacked")
        assert factory.load_entry_points([evil]) == []
    finally:
        logger.removeHandler(handler)
    assert factory.create("openai") == ("openai", "small")
    assert any("openai" in m for m in handler.messages)


def test_concurrent_first_use_loads_the_plugin_once() -> None:
    factory = ProviderFactory()
    ep = FakeEntryPoint("local", target=lambda: object())
    factory.load_entry_points([ep])
    barrier = threading.Barrier(8)
    results = []

    def worker():
        barrier.wait()
        results.append(factory.create("local"))

    threads = [threading.Thread(target=worker) for _ in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert ep.load_calls == 1 and len(results) == 8
```

